export const DOUBLE_SUBMIT_LIMITS = Object.freeze({
  pendingWindowMs: 10_000,
  maxTriesAfterError: 1,
});

export interface SubmitFacts {
  origin: string;
  path: string;
  formKey: string;
  /** Button label from the browser mask layer. */
  label: string;
  method: string;
}

type SubmitOutcome = "pending" | "navigated" | "confirmed" | "error-shown" | "unknown";

export interface EarlierSubmit extends SubmitFacts {
  /** Job log identifier generated by the caller. */
  stepId?: string;
  at: number;
  outcome: SubmitOutcome;
}

export interface DoubleSubmitInput {
  submit: SubmitFacts;
  /** One masked record per press, including any press still in flight. */
  previousSubmits: readonly EarlierSubmit[];
  now: number;
}

export interface DoubleSubmitDecision {
  action: "submit" | "wait" | "hold" | "refuse";
  reason: string;
  matchedStepId?: string;
}

const outcomes: ReadonlySet<SubmitOutcome> = new Set(["pending", "navigated", "confirmed", "error-shown", "unknown"]);

function hasText(value: unknown): value is string {
  return typeof value === "string" && value.trim().length > 0;
}

function submitOrigin(facts: SubmitFacts | null | undefined): URL | null {
  if (!facts || typeof facts.origin !== "string" || typeof facts.path !== "string" ||
    !facts.path.startsWith("/") || /[?#\\\p{Cc}]/u.test(facts.path) ||
    !hasText(facts.formKey) || !hasText(facts.label) ||
    typeof facts.method !== "string" || !/^[!#$%&'*+.^_`|~\w-]+$/.test(facts.method)) {
    return null;
  }

  // Only accept HTTP(S) origins, so credentials and other URL components stay out of reasons.
  if (!/^https?:\/\/[^/?#@\\\s\p{Cc}]+\/?$/iu.test(facts.origin)) return null;
  try {
    return new URL(facts.origin);
  } catch {
    return null;
  }
}

function validTime(value: number): boolean {
  return Number.isFinite(value) && value >= 0;
}

function decision(
  action: DoubleSubmitDecision["action"], reason: string, step?: EarlierSubmit,
): DoubleSubmitDecision {
  return step?.stepId === undefined ? { action, reason } : { action, reason, matchedStepId: step.stepId };
}

/** Check one proposed press against the job's masked submit history. Times are milliseconds on the same clock. */
export function doubleSubmitRule(input: DoubleSubmitInput): DoubleSubmitDecision {
  const badInput: DoubleSubmitDecision = { action: "hold", reason: "Hold for Amit because the submit details are incomplete or invalid." };
  if (!input || !Array.isArray(input.previousSubmits) || !validTime(input.now)) return badInput;

  const { submit, previousSubmits, now } = input;
  const page = submitOrigin(submit);
  if (!page) return badInput;

  const matches: EarlierSubmit[] = [];
  for (const step of previousSubmits) {
    const origin = submitOrigin(step);
    if (!origin || !validTime(step.at) || step.at > now || !outcomes.has(step.outcome) ||
      (step.stepId !== undefined && !hasText(step.stepId))) {
      return badInput;
    }
    if (origin.origin === page.origin && step.path === submit.path && step.formKey === submit.formKey) matches.push(step);
  }

  const host = page.hostname;
  if (matches.length === 0) return decision("submit", `This form has no earlier press on ${host}.`);

  // An error on a later press cannot clear a success or uncertainty from an earlier press.
  matches.sort((a, b) => b.at - a.at);
  const completed = matches.find((step) => step.outcome === "navigated" || step.outcome === "confirmed");
  if (completed) return decision("refuse", `This form already went through on ${host}.`, completed);

  const uncertain = matches.find((step) => step.outcome === "unknown" ||
    (step.outcome === "pending" && now - step.at >= DOUBLE_SUBMIT_LIMITS.pendingWindowMs));
  if (uncertain) return decision("hold", `Hold for Amit because the first press may already have gone through on ${host}.`, uncertain);

  const pending = matches.find((step) => step.outcome === "pending");
  if (pending) return decision("wait", `Wait for the earlier press on ${host} to finish.`, pending);

  if (matches.length <= DOUBLE_SUBMIT_LIMITS.maxTriesAfterError) {
    return decision("submit", `The form showed an error on ${host} and can be pressed once more.`, matches[0]);
  }
  return decision("hold", `Hold for Amit because the form on ${host} already used its retry.`, matches[0]);
}
